const bookings = $input.all();

const now = new Date();

return bookings.map(item => {
    const b = item.json;

    const departure = new Date(b.departure_ts);

    const hoursUntilDeparture =
        (departure.getTime() - now.getTime()) / (1000 * 60 * 60);

    // Send reminder when departure is within 24 hours.
    const reminderDue =
        hoursUntilDeparture > 0 &&
        hoursUntilDeparture <= 24;

    return {
        json: {
            booking_id: b.booking_id,
            passenger_id: b.passenger_id,
            passenger_name: b.full_name,
            email: b.email,

            flight_number: b.flight_number,
            origin: b.origin,
            destination: b.destination,

            origin_timezone: b.origin_timezone,
            destination_timezone: b.destination_timezone,

            departure_local_time: b.departure_local_time,
            arrival_local_time: b.arrival_local_time,

            hours_until_departure:
                Math.round(hoursUntilDeparture * 100) / 100,

            reminder_due: reminderDue,

            reminder_type: "check_in_reminder"
        }
    };
});
